/**
 * ENG-2782 S2 — GET /embed/slack-start.js: the "Get started in Slack" widget for
 * script-tag embeds. The bundle is generated by packages/slack-start
 * (`npm run build`) into embed/slackStartBundle.generated.ts so it ships inside
 * backend/dist. It is public static code: any origin may load it. The API it
 * calls applies its own origin allowlist (routes/slackStart.ts).
 */
import express from 'express';
import { SLACK_START_BUNDLE, SLACK_START_BUNDLE_SHA256 } from '../embed/slackStartBundle.generated';

const router = express.Router();
const ETAG = `"${SLACK_START_BUNDLE_SHA256}"`;

router.get('/slack-start.js', (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'public, max-age=300, stale-while-revalidate=86400');
  res.setHeader('ETag', ETAG);
  if (req.headers['if-none-match'] === ETAG) return res.status(304).end();
  res.type('application/javascript; charset=utf-8').send(SLACK_START_BUNDLE);
});

export default router;
